import{f as i,c as s,o as t,ah as e}from"./chunks/framework.5bt9HFMa.js";const c=JSON.parse('{"title":"GitHub食用指南","description":"","frontmatter":{"title":"GitHub食用指南","date":"2024-09-12T00:00:00.000Z","category":"GitHub","tags":["GitHub","Git","代码管理","版本控制"]},"headers":[],"relativePath":"posts/GitHub食用指南.md","filePath":"posts/GitHub食用指南.md","lastUpdated":1763891420000}'),h={name:"posts/GitHub食用指南.md"};function l(n,a,p,r,o,d){return t(),s("div",null,a[0]||(a[0]=[e(`<h1 id="github食用指南" tabindex="-1">GitHub食用指南 <a class="header-anchor" href="#github食用指南" aria-label="Permalink to &quot;GitHub食用指南&quot;">​</a></h1><p>很多大学新生都会遇到一个问题——老师要求把代码上传到仓库。可是，什么是仓库？我们又该如何实现呢？通过本文，你将学习如何使用GitHub来管理代码！</p><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><h3 id="_1-什么是github" tabindex="-1">1. 什么是GitHub？ <a class="header-anchor" href="#_1-什么是github" aria-label="Permalink to &quot;1. 什么是GitHub？&quot;">​</a></h3><p>GitHub是一个基于Git的代码托管平台，允许开发者存储、管理和共享代码仓库。</p><p>现在比较常见的代码仓库有Gitee、GitHub等。</p><p><strong>Gitee</strong>：<a href="https://gitee.com/" target="_blank" rel="noreferrer">https://gitee.com/</a></p><p>Gitee是国内的代码托管平台，服务器在中国境内，速度更快更方便。</p><p><strong>GitHub</strong>：<a href="https://github.com/" target="_blank" rel="noreferrer">https://github.com/</a></p><p>GitHub是国际著名的代码托管平台，能提供更好的社区支持。</p><p>两个网站功能上区别不大，Gitee服务器在中国境内，速度更快更方便，GitHub能提供更好的社区支持。</p><p>本文档将基于GitHub来讲解如何使用Git来进行代码管理的讲解。</p><p>如果你想在国内访问GitHub，可以下载<a href="https://steampp.net/" target="_blank" rel="noreferrer">Watt Toolkit</a>提供的代理支持。</p><h3 id="_2-什么是仓库" tabindex="-1">2. 什么是仓库？ <a class="header-anchor" href="#_2-什么是仓库" aria-label="Permalink to &quot;2. 什么是仓库？&quot;">​</a></h3><p>仓库（Repository）是一个项目的存储空间，可以包含项目的所有文件和每个文件的修订历史记录。你可以将仓库看作是一个项目的文件夹。</p><p>在初次初始化后将会在项目文件夹下面生成 <code>.git</code> 文件夹，这个文件夹包含了所有的版本控制信息。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="_1-下载git" tabindex="-1">1. 下载Git <a class="header-anchor" href="#_1-下载git" aria-label="Permalink to &quot;1. 下载Git&quot;">​</a></h3><p>Git是一个免费的开源分布式版本控制系统。一切对仓库的操作都是基于git的操作。你可以从<a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git官方网站</a>下载并安装Git。</p><h4 id="从git官网下载" tabindex="-1">从Git官网下载 <a class="header-anchor" href="#从git官网下载" aria-label="Permalink to &quot;从Git官网下载&quot;">​</a></h4><ol><li>打开 <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git官方网站</a>。</li><li>点击页面上的&quot;Download&quot;按钮，系统会自动检测你的操作系统并提供相应的下载链接。</li><li>下载完成后，运行安装程序并按照提示完成安装。</li></ol><p>我也在百度网盘上上传了最新版的git 64位安装程序：<a href="https://pan.baidu.com/s/1bqaT_GcfcyetGnHyK7r5_g?pwd=vhhs" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1bqaT_GcfcyetGnHyK7r5_g?pwd=vhhs</a></p><h4 id="配置git" tabindex="-1">配置Git <a class="header-anchor" href="#配置git" aria-label="Permalink to &quot;配置Git&quot;">​</a></h4><p>安装完成后，你需要进行一些基本配置来设置你的Git环境。</p><h5 id="设置用户名和邮箱" tabindex="-1">设置用户名和邮箱 <a class="header-anchor" href="#设置用户名和邮箱" aria-label="Permalink to &quot;设置用户名和邮箱&quot;">​</a></h5><p>Git会使用这些信息来记录每次提交的作者信息。运行以下命令来设置你的用户名和邮箱：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的用户名&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的邮箱地址&quot;</span></span></code></pre></div><h5 id="验证配置" tabindex="-1">验证配置 <a class="header-anchor" href="#验证配置" aria-label="Permalink to &quot;验证配置&quot;">​</a></h5><p>你可以使用以下命令来查看配置是否成功：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span></code></pre></div><h3 id="_2-注册github" tabindex="-1">2. 注册Github <a class="header-anchor" href="#_2-注册github" aria-label="Permalink to &quot;2. 注册Github&quot;">​</a></h3><p>要使用GitHub来管理你的代码，首先需要注册一个GitHub账户。以下是注册步骤：</p><h4 id="访问github网站" tabindex="-1">访问GitHub网站 <a class="header-anchor" href="#访问github网站" aria-label="Permalink to &quot;访问GitHub网站&quot;">​</a></h4><p>打开浏览器，访问<a href="https://github.com/" target="_blank" rel="noreferrer">GitHub官方网站</a>。</p><h4 id="创建账户" tabindex="-1">创建账户 <a class="header-anchor" href="#创建账户" aria-label="Permalink to &quot;创建账户&quot;">​</a></h4><p>在 GitHub 首页，点击右上角的 &quot;Sign up&quot; 按钮，进入注册页面。</p><h4 id="填写注册信息" tabindex="-1">填写注册信息 <a class="header-anchor" href="#填写注册信息" aria-label="Permalink to &quot;填写注册信息&quot;">​</a></h4><p>在注册页面，填写你的用户名、邮箱地址和密码，然后点击&quot;Create account&quot;按钮。</p><h4 id="验证邮箱" tabindex="-1">验证邮箱 <a class="header-anchor" href="#验证邮箱" aria-label="Permalink to &quot;验证邮箱&quot;">​</a></h4><p>GitHub会向你提供的邮箱地址发送一封验证邮件。打开你的邮箱，找到这封邮件并点击其中的验证链接，完成邮箱验证。</p><h4 id="完成注册" tabindex="-1">完成注册 <a class="header-anchor" href="#完成注册" aria-label="Permalink to &quot;完成注册&quot;">​</a></h4><p>根据页面提示，完成剩余的注册步骤，包括选择账户类型和设置个人偏好等。</p><p>注册完成后，你就可以登录GitHub并创建新的代码仓库了。</p><h3 id="_3-初始化本地仓库" tabindex="-1">3. 初始化本地仓库 <a class="header-anchor" href="#_3-初始化本地仓库" aria-label="Permalink to &quot;3. 初始化本地仓库&quot;">​</a></h3><p>在你注册并登录GitHub后，可以开始在本地创建一个新的Git仓库，并将其连接到GitHub上的远程仓库。</p><h4 id="创建本地项目文件夹" tabindex="-1">创建本地项目文件夹 <a class="header-anchor" href="#创建本地项目文件夹" aria-label="Permalink to &quot;创建本地项目文件夹&quot;">​</a></h4><p>首先，在你的计算机上创建一个新的文件夹，用于存放你的项目文件。</p><h4 id="初始化git仓库" tabindex="-1">初始化Git仓库 <a class="header-anchor" href="#初始化git仓库" aria-label="Permalink to &quot;初始化Git仓库&quot;">​</a></h4><p>在项目文件夹中初始化一个新的 Git 仓库。在当前文件夹打开命令提示符（cmd），运行以下命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>这将创建一个名为 <code>.git</code> 的隐藏文件夹，Git会在其中存储版本控制信息。</p><h4 id="进行项目更改并提交本地仓库" tabindex="-1">进行项目更改并提交本地仓库 <a class="header-anchor" href="#进行项目更改并提交本地仓库" aria-label="Permalink to &quot;进行项目更改并提交本地仓库&quot;">​</a></h4><h5 id="创建-readme-文件" tabindex="-1">创建 README 文件 <a class="header-anchor" href="#创建-readme-文件" aria-label="Permalink to &quot;创建 README 文件&quot;">​</a></h5><p>在项目文件夹中创建一个 <code>README.md</code> 文件，并添加一些描述信息：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 我的项目</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这是我的第一个GitHub项目。</span></span></code></pre></div><h5 id="添加文件到-git-索引" tabindex="-1">添加文件到 Git 索引 <a class="header-anchor" href="#添加文件到-git-索引" aria-label="Permalink to &quot;添加文件到 Git 索引&quot;">​</a></h5><p>使用以下命令将 README 文件添加到 Git 索引中：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 添加 README.md 到本地仓库</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或者</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 将当前文件夹添加到本地仓库</span></span></code></pre></div><h5 id="提交更改" tabindex="-1">提交更改 <a class="header-anchor" href="#提交更改" aria-label="Permalink to &quot;提交更改&quot;">​</a></h5><p>将README文件的更改提交到本地仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的提交信息&quot;</span></span></code></pre></div><h3 id="_4-推送到远程服务器" tabindex="-1">4. 推送到远程服务器 <a class="header-anchor" href="#_4-推送到远程服务器" aria-label="Permalink to &quot;4. 推送到远程服务器&quot;">​</a></h3><p>在你完成本地仓库的初始化和更改提交后，可以将这些更改推送到GitHub上的远程仓库。</p><h4 id="连接到-github-远程仓库" tabindex="-1">连接到 GitHub 远程仓库 <a class="header-anchor" href="#连接到-github-远程仓库" aria-label="Permalink to &quot;连接到 GitHub 远程仓库&quot;">​</a></h4><p>在 GitHub 上点击 &quot;New&quot; 创建一个新的仓库，然后将其 URL 复制下来。</p><p>使用以下命令将本地仓库连接到GitHub上的远程仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/your-username/your-repo.git</span></span></code></pre></div><h4 id="推送更改" tabindex="-1">推送更改 <a class="header-anchor" href="#推送更改" aria-label="Permalink to &quot;推送更改&quot;">​</a></h4><p>将本地仓库的更改推送到GitHub上的远程仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre></div><p>这将把本地仓库中的所有提交推送到远程仓库的master分支。</p><h4 id="验证推送" tabindex="-1">验证推送 <a class="header-anchor" href="#验证推送" aria-label="Permalink to &quot;验证推送&quot;">​</a></h4><p>推送完成后，你可以在GitHub页面上查看你的项目，确认所有更改已经成功上传。</p><p>现在，你的本地仓库已经成功推送到GitHub上的远程仓库，你可以随时在本地进行更改并推送到远程仓库，以保持代码的同步和备份。</p><h2 id="后续操作" tabindex="-1">后续操作 <a class="header-anchor" href="#后续操作" aria-label="Permalink to &quot;后续操作&quot;">​</a></h2><p>同时GitHub也是一个非常好的学习编程的网站，你可以查看他人的项目，并在本地进行部署。</p><h3 id="_1-克隆远程仓库" tabindex="-1">1. 克隆远程仓库 <a class="header-anchor" href="#_1-克隆远程仓库" aria-label="Permalink to &quot;1. 克隆远程仓库&quot;">​</a></h3><p>如果你想在另一台计算机上继续你的项目、下载他人项目或者与他人协作，你需要克隆远程仓库。在仓库的 Code 页面里可以查看仓库 URL。</p><p>使用以下命令克隆远程仓库到本地：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/your-username/your-repo.git</span></span></code></pre></div><p>这将创建一个包含远程仓库所有内容的本地副本。</p><h3 id="_2-拉取最新更改" tabindex="-1">2. 拉取最新更改 <a class="header-anchor" href="#_2-拉取最新更改" aria-label="Permalink to &quot;2. 拉取最新更改&quot;">​</a></h3><p>在多人协作的项目中，你需要定期拉取远程仓库的最新更改。使用以下命令拉取最新更改：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre></div><p>这将从远程仓库的<code>master</code>分支拉取最新的更改并合并到你的本地分支。</p><h3 id="_3-合并操作" tabindex="-1">3. 合并操作 <a class="header-anchor" href="#_3-合并操作" aria-label="Permalink to &quot;3. 合并操作&quot;">​</a></h3><p>在多人协作的项目中，不同的开发者可能会在不同的分支上工作。你需要将这些分支合并到主分支。</p><h4 id="切换到目标分支" tabindex="-1">切换到目标分支 <a class="header-anchor" href="#切换到目标分支" aria-label="Permalink to &quot;切换到目标分支&quot;">​</a></h4><p>首先，切换到你想要合并到的目标分支（例如 <code>master</code> 分支）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre></div><h4 id="合并分支" tabindex="-1">合并分支 <a class="header-anchor" href="#合并分支" aria-label="Permalink to &quot;合并分支&quot;">​</a></h4><p>使用以下命令将另一个分支（例如 <code>feature-branch</code> ）合并到当前分支：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-branch</span></span></code></pre></div><h4 id="解决冲突" tabindex="-1">解决冲突 <a class="header-anchor" href="#解决冲突" aria-label="Permalink to &quot;解决冲突&quot;">​</a></h4><p>如果在合并过程中出现冲突，Git会提示你解决冲突。打开冲突文件，手动解决冲突后，使用以下命令标记冲突已解决：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conflict-file</span></span></code></pre></div><h4 id="提交合并" tabindex="-1">提交合并 <a class="header-anchor" href="#提交合并" aria-label="Permalink to &quot;提交合并&quot;">​</a></h4><p>最后，提交合并结果：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;合并分支 feature-branch&quot;</span></span></code></pre></div>`,99)]))}const b=i(h,[["render",l]]);export{c as __pageData,b as default};
